ledger = [
    {"id": "R1", "kind": "functional",     "status": "confirmed"},
    {"id": "R2", "kind": "non-functional", "status": "draft"},
    {"id": "R3", "kind": "non-functional", "status": "confirmed"},
    {"id": "R4", "kind": "functional",     "status": "draft"},
]

for r in ledger:
    if r["status"] == "draft":
        print(r["id"], r["kind"])

n = 0
for r in ledger:
    if r["status"] == "draft":
        n += 1
print("drafts:", n)

def check(story):
    if not story.startswith("As a "):
        return "missing role"
    if ", I want " not in story:
        return "missing capability"
    if ", so that " not in story:
        return "missing goal"
    return "OK"

cards = [
    "As a nurse, I want today's schedule, so that I plan rounds.",
    "As a user, I want faster search.",
    "I want it modern.",
]
for i, c in enumerate(cards, 1):
    print(i, check(c))

